<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { HttpStaffApi } from "../features/staff/api";
import type { QuestionBankSummary, QuestionDraft, QuestionSummary } from "../features/staff/types";
import { messageFrom, safeHtmlPreview } from "../features/staff/helpers";
import ScopeSwitcher from "../components/ScopeSwitcher.vue";

const api = new HttpStaffApi();
const items = ref<readonly QuestionSummary[]>([]);
const banks = ref<readonly QuestionBankSummary[]>([]);
const query = ref("");
const loading = ref(true);
const error = ref("");
const selected = ref<QuestionDraft | null>(null);
const saving = ref(false);
const bankSaving = ref(false);
const showBankForm = ref(false);
const bankForm = ref({ subjectId: "", name: "" });
const report = ref<{ isReady: boolean; issues: readonly { severity: string; message: string; fieldPath: string }[] } | null>(null);
const form = ref({ questionBankId: "", type: "SINGLE_CHOICE", stimulusHtml: "", promptHtml: "", explanationHtml: "", options: [{ contentHtml: "", isCorrect: false }, { contentHtml: "", isCorrect: false }], statements: [{ statementHtml: "", correctValue: true }, { statementHtml: "", correctValue: false }, { statementHtml: "", correctValue: false }] });
const dirty = computed(() => Boolean(selected.value) && !saving.value);

async function load(): Promise<void> { loading.value = true; error.value = ""; try { const [questionPage, bankPage] = await Promise.all([api.questions(query.value), api.questionBanks()]); items.value = questionPage.items; banks.value = bankPage.items; } catch (cause) { error.value = messageFrom(cause, "Bank soal belum tersedia."); } finally { loading.value = false; } }
async function createBank(): Promise<void> { bankSaving.value = true; error.value = ""; try { const bank = await api.createQuestionBank({ subjectId: bankForm.value.subjectId, name: bankForm.value.name }); banks.value = [bank, ...banks.value]; bankForm.value = { subjectId: "", name: "" }; showBankForm.value = false; } catch (cause) { error.value = messageFrom(cause, "Bank soal belum dapat dibuat."); } finally { bankSaving.value = false; } }
function open(item?: QuestionSummary): void {
  report.value = null;
  if (!item) { selected.value = { id: "new", questionId: "new", questionBank: { id: "", name: "Bank baru", subjectId: "" }, revisionNo: 1, type: "SINGLE_CHOICE", status: "DRAFT", stimulusHtml: "", promptHtml: "", explanationHtml: "", options: [], statements: [], updatedAt: "" }; form.value = { ...form.value, questionBankId: "", type: "SINGLE_CHOICE", stimulusHtml: "", promptHtml: "", explanationHtml: "" }; return; }
  void api.question(item.id).then((draft) => { selected.value = draft; form.value = { questionBankId: draft.questionBank.id, type: draft.type, stimulusHtml: draft.stimulusHtml, promptHtml: draft.promptHtml ?? "", explanationHtml: draft.explanationHtml ?? "", options: draft.options.map((option) => ({ contentHtml: option.contentHtml, isCorrect: option.isCorrect })), statements: draft.statements.map((statement) => ({ statementHtml: statement.statementHtml, correctValue: statement.correctValue })) }; }).catch((cause) => { error.value = messageFrom(cause); });
}
function close(): void { selected.value = null; report.value = null; }
function addOption(): void { if (form.value.options.length < 10) form.value.options.push({ contentHtml: "", isCorrect: false }); }
function addStatement(): void { if (form.value.statements.length < 3) form.value.statements.push({ statementHtml: "", correctValue: false }); }
async function save(): Promise<void> {
  if (!selected.value) return; saving.value = true; error.value = "";
  try {
    const payload = { type: form.value.type, stimulusHtml: form.value.stimulusHtml, promptHtml: form.value.type === "TRUE_FALSE" ? null : form.value.promptHtml || null, explanationHtml: form.value.explanationHtml || null, options: form.value.type === "TRUE_FALSE" ? [] : form.value.options.map((item, index) => ({ position: index + 1, ...item })), statements: form.value.type === "TRUE_FALSE" ? form.value.statements.map((item, index) => ({ position: index + 1, ...item })) : [] };
    selected.value = selected.value.id === "new" ? await api.createQuestion({ questionBankId: form.value.questionBankId, ...payload }) : await api.updateQuestion(selected.value.id, payload, selected.value.updatedAt);
    report.value = null;
    await load();
  } catch (cause) { error.value = messageFrom(cause); } finally { saving.value = false; }
}
async function validate(): Promise<void> { if (!selected.value || selected.value.id === "new") { report.value = { isReady: false, issues: [{ severity: "ERROR", message: "Simpan draft sebelum validasi.", fieldPath: "" }] }; return; } try { report.value = await api.validateQuestion(selected.value.id); } catch (cause) { error.value = messageFrom(cause); } }
async function publish(): Promise<void> { if (!selected.value || !report.value?.isReady) return; if (!window.confirm("Publish revision soal? Setelah publish, revisi menjadi immutable.")) return; try { selected.value = await api.publishQuestion(selected.value.id, selected.value.updatedAt); await load(); } catch (cause) { error.value = messageFrom(cause); } }
onMounted(() => { void load(); });
</script>

<template>
  <header class="page-heading between"><div><p class="eyebrow">Guru · Authoring</p><h1>Bank Soal</h1><p class="muted">Buat bank dan validasi tiga tipe soal dengan answer key hanya di area staff.</p></div><div class="stack"><button class="btn-secondary" type="button" @click="showBankForm = !showBankForm">Buat bank</button><button class="btn-primary" type="button" @click="open()">Buat soal</button></div></header>
  <section v-if="showBankForm" class="card bank-form"><form class="form-grid" @submit.prevent="createBank"><label>Subject ID<input v-model="bankForm.subjectId" inputmode="numeric" pattern="[0-9]+" required /></label><label>Nama bank<input v-model="bankForm.name" maxlength="200" required /></label><button class="btn-primary" type="submit" :disabled="bankSaving">{{ bankSaving ? "Menyimpan…" : "Simpan bank" }}</button></form></section>
  <ScopeSwitcher :dirty="dirty" />
  <div class="toolbar"><form class="search-form" @submit.prevent="load"><label class="sr-only" for="question-search">Cari soal</label><input id="question-search" v-model="query" placeholder="Cari stimulus, bank, atau tipe" /><button class="btn-secondary" type="submit">Cari</button></form><span class="muted">{{ items.length }} item</span></div>
  <div v-if="error" class="alert alert-error" role="alert">{{ error }}</div>
  <section class="card table-card"><div v-if="loading" class="table-state">Memuat bank soal…</div><div v-else-if="items.length === 0" class="table-state"><strong>Belum ada soal</strong><span class="muted">Buat draft pertama dari tombol di atas.</span></div><div v-else class="table-scroll"><table><caption class="sr-only">Daftar soal</caption><thead><tr><th>Preview</th><th>Type</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{ item.bankName }}</strong><small>{{ safeHtmlPreview(item.label) }}</small></td><td>{{ item.type }}</td><td><span class="badge" :class="item.status === 'PUBLISHED' ? 'badge-success' : 'badge-warning'">{{ item.status }}</span></td><td>{{ item.updatedAt }}</td><td><button class="btn-quiet" type="button" @click="open(item)">Buka editor</button></td></tr></tbody></table></div></section>
  <div v-if="selected" class="overlay" role="dialog" aria-modal="true" aria-labelledby="question-editor-title"><section class="drawer"><div class="between"><div><p class="eyebrow">{{ selected.status }}</p><h2 id="question-editor-title">Editor soal</h2></div><button class="btn-quiet" type="button" @click="close">Tutup</button></div><form @submit.prevent="save"><div v-if="selected.id === 'new'" class="form-row"><label for="question-bank-id">Bank soal</label><select id="question-bank-id" v-model="form.questionBankId" required><option value="" disabled>Pilih bank soal</option><option v-for="bank in banks" :key="bank.id" :value="bank.id">{{ bank.name }} · subject {{ bank.subjectId }}</option></select><small v-if="banks.length === 0" class="muted">Buat bank soal terlebih dahulu.</small></div><div class="form-row"><label for="question-type">Tipe soal</label><select id="question-type" v-model="form.type"><option value="SINGLE_CHOICE">Single choice · exact match</option><option value="MULTIPLE_RESPONSE">Multiple response · semua tepat</option><option value="TRUE_FALSE">True/False · tiga pernyataan</option></select></div><div class="form-row"><label for="stimulus">Stimulus</label><textarea id="stimulus" v-model="form.stimulusHtml" rows="4" required /></div><div v-if="form.type !== 'TRUE_FALSE'" class="form-row"><label for="prompt">Pertanyaan</label><textarea id="prompt" v-model="form.promptHtml" rows="3" required /></div><div v-if="form.type !== 'TRUE_FALSE'" class="child-editor"><div class="between"><h3>Opsi jawaban</h3><button class="btn-quiet" type="button" @click="addOption">Tambah opsi</button></div><div v-for="(option, index) in form.options" :key="index" class="child-row"><input v-model="option.contentHtml" :aria-label="`Isi opsi ${index + 1}`" required /><label><input v-model="option.isCorrect" type="checkbox" /> benar</label></div><p class="muted small-copy">Single choice harus tepat satu benar; multiple response minimal satu dan semua key harus tepat.</p></div><div v-else class="child-editor"><div class="between"><h3>Tiga pernyataan</h3><button class="btn-quiet" type="button" @click="addStatement">Tambah</button></div><div v-for="(statement, index) in form.statements" :key="index" class="child-row"><input v-model="statement.statementHtml" :aria-label="`Pernyataan ${index + 1}`" required /><select v-model="statement.correctValue" :aria-label="`Jawaban pernyataan ${index + 1}`"><option :value="true">Benar</option><option :value="false">Salah</option></select></div></div><div class="form-row"><label for="explanation">Penjelasan (opsional)</label><textarea id="explanation" v-model="form.explanationHtml" rows="3" /></div><div v-if="report" class="readiness" :class="report.isReady ? 'ready' : 'blocked'"><strong>{{ report.isReady ? 'Siap dipublish' : 'Belum siap dipublish' }}</strong><ul><li v-for="issue in report.issues" :key="`${issue.fieldPath}-${issue.message}`">{{ issue.severity }} · {{ issue.message }} <button v-if="issue.fieldPath" class="link-button" type="button">Buka field</button></li></ul></div><div class="editor-actions"><button class="btn-secondary" type="button" :disabled="saving" @click="validate">Validasi</button><button class="btn-primary" type="submit" :disabled="saving">{{ saving ? 'Menyimpan…' : 'Simpan draft' }}</button><button v-if="selected.status === 'DRAFT'" class="btn-secondary" type="button" :disabled="saving || !report?.isReady" @click="publish">Publish</button></div></form></section></div>
</template>

<style scoped>
.page-heading { align-items: flex-start; margin-bottom: 18px; }.page-heading h1 { margin: 0 0 6px; }.eyebrow { margin: 0 0 4px; color: var(--primary); font-weight: 700; }.toolbar { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin: 16px 0; }.search-form { display: flex; gap: 8px; }.search-form input { min-height: 40px; min-width: min(360px, 55vw); }.table-card { padding: 20px; }.table-scroll { overflow-x: auto; } table { width: 100%; border-collapse: collapse; } th, td { padding: 12px 10px; text-align: left; border-bottom: 1px solid var(--border); vertical-align: top; } th { color: var(--muted); font-size: .8rem; } td small { display: block; color: var(--subtle); margin-top: 4px; }.table-state { display: grid; gap: 6px; justify-items: center; padding: 42px 12px; }.badge { display: inline-flex; padding: 4px 8px; border-radius: 99px; background: var(--primary-soft); color: var(--primary); font-size: .78rem; font-weight: 700; }.badge-success { color: var(--success); background: var(--success-soft); }.badge-warning { color: var(--warning); background: var(--warning-soft); }.overlay { position: fixed; inset: 0; z-index: 20; display: flex; justify-content: flex-end; background: rgb(2 6 23 / 45%); }.drawer { width: min(680px, 100%); height: 100%; overflow: auto; padding: 24px; background: var(--surface); box-shadow: var(--shadow); }.form-row textarea, .form-row select { width: 100%; border: 1px solid var(--border-strong); border-radius: 8px; padding: 8px 10px; color: var(--text); background: var(--surface); }.child-editor { margin: 16px 0; padding: 14px; border: 1px solid var(--border); border-radius: 10px; }.child-editor h3 { margin: 0; }.child-row { display: grid; grid-template-columns: 1fr auto; gap: 8px; align-items: center; margin: 10px 0; }.child-row input:not([type='checkbox']), .child-row select { min-height: 40px; width: 100%; border: 1px solid var(--border-strong); border-radius: 8px; padding: 8px; background: var(--surface); color: var(--text); }.readiness { margin: 16px 0; padding: 12px; border-radius: 8px; }.readiness.ready { color: var(--success); background: var(--success-soft); }.readiness.blocked { color: var(--danger); background: var(--danger-soft); }.readiness ul { margin-bottom: 0; padding-left: 20px; }.link-button { border: 0; min-height: auto; padding: 0; color: inherit; background: transparent; text-decoration: underline; }.editor-actions { display: flex; flex-wrap: wrap; gap: 8px; }.small-copy { font-size: .84rem; }.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 600px) { .page-heading, .toolbar { display: grid; align-items: stretch; }.search-form input { min-width: 0; flex: 1; } .drawer { padding: 18px 14px; } }
</style>
